import math

k = 2 ** (1/3)

def f(n):
    return int(n / k)

# Extend search to larger range
solutions = []
N = 1000
for a in range(2, N):
    if f(a) == 0:
        continue
    fa = f(a)
    for b in range(a, N):
        fb = f(b)
        if fb == 0:
            continue
        # For given a, b: need c such that a*b*c = 5*fa*fb*f(c)
        # i.e., c/f(c) = 5*fa*fb/(a*b)
        # Since c/f(c) is between roughly 1 and 2, we need 5*fa*fb/(a*b) in [1,2]
        # i.e., a*b <= 5*fa*fb <= 2*a*b
        target_ratio = 5 * fa * fb / (a * b)
        if target_ratio < 1.0 or target_ratio > 2.0:
            continue
        # Search for c >= b with c/f(c) = target_ratio, i.e., a*b*c = 5*fa*fb*f(c)
        # c must satisfy: a*b*c = 5*fa*fb*f(c)
        # Try c in range [b, N]
        for c in range(b, N):
            fc = f(c)
            if fc == 0:
                continue
            if a * b * c == 5 * fa * fb * fc:
                solutions.append((a, b, c))

print(f"Solutions found (a<=b<=c, up to {N}):")
for s in solutions:
    a, b, c = s
    print(f"  ({a}, {b}, {c}): abc={a*b*c}, f={f(a)},{f(b)},{f(c)}, 5*f(a)f(b)f(c)={5*f(a)*f(b)*f(c)}")

# Also show r(n) = n/f(n) for small n to understand the structure
print("\nr(n) = n/f(n) for n=2..30:")
for n in range(2, 31):
    fn = f(n)
    if fn > 0:
        print(f"  n={n}: f={fn}, r={n/fn:.6f} = {n}/{fn}")
